<?php
namespace App\Services;use App\Models\FeeInvoice;use App\Models\FeePayment;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class FeePaymentService {public function record(FeeInvoice $invoice,array $data):FeePayment{return DB::transaction(function()use($invoice,$data){$invoice=FeeInvoice::lockForUpdate()->findOrFail($invoice->id);$paid=$invoice->payments()->sum('amount');$balance=$invoice->amount_due-$paid;if($data['amount']<=0||$data['amount']>$balance)throw ValidationException::withMessages(['amount'=>'Payment must be greater than zero and cannot exceed the outstanding balance.']);$payment=$invoice->payments()->create($data+['school_id'=>$invoice->school_id,'receipt_no'=>$this->receiptNumber($invoice)]);$newBalance=$balance-$payment->amount;$invoice->update(['status'=>$newBalance<=0?'paid':'partial']);return $payment;});}private function receiptNumber(FeeInvoice $invoice):string{return strtoupper($invoice->school->slug).'-'.now()->format('ymd').'-'.str_pad((string)(FeePayment::where('school_id',$invoice->school_id)->lockForUpdate()->count()+1),6,'0',STR_PAD_LEFT);}}
